class Solution {
public:
    string removeDuplicateLetters(string s) {
        int cnt[26] = {0};
        for (char c : s) cnt[c - 'a']++;

        bool inStack[26] = {false};
        string st;                     // used as a stack

        for (char c : s) {
            int idx = c - 'a';
            cnt[idx]--;                // one occurrence is now processed

            if (inStack[idx]) continue; // already taken

            while (!st.empty() && c < st.back() && cnt[st.back() - 'a'] > 0) {
                inStack[st.back() - 'a'] = false;
                st.pop_back();
            }
            st.push_back(c);
            inStack[idx] = true;
        }
        return st;
    }
};
